/**
 * Pricing 3 Component
 *
 * Source: https://tailark.com/preview/dusk/pricing/three
 * License: Free Tier
 * Adapted from: Tailark
 *
 * Modifications:
 * - Integrated with PayloadCMS block system
 * - Replaced hardcoded content with dynamic props
 */


import { Check } from "lucide-react";
import Link from "next/link";

import type { Pricing_3_Block } from "~/payload-types";

import { cn } from "@/registry/default/utils";
import { Button } from "@/registry/ui/button";
import {
	Card,
	CardContent,
	CardDescription,
	CardHeader,
	CardTitle,
} from "@/registry/ui/card";

export * from "./config";

export default function Pricing3(props: NonNullable<Pricing_3_Block>) {
	const popularIndex = props?.config?.popularIndex ?? -1;
	const popularLabel = props?.config?.popularLabel ?? "Popular";

	return (
		<section className="py-16 md:py-32">
			<div className="mx-auto max-w-7xl px-6">
				{/* Header Section */}
				<div className="mx-auto max-w-3xl space-y-4 text-center">
					{props?.header && (
						<h2 className="text-4xl font-semibold lg:text-5xl">
							{props.header}
						</h2>
					)}
					{props?.subheader && (
						<p className="text-muted-foreground text-lg">
							{props.subheader}
						</p>
					)}
				</div>

				{/* Pricing Cards Grid */}
				<div className="mt-12 grid gap-6 md:mt-16 md:grid-cols-3">
					{(props?.tiers ?? []).map((tier, index) => {
						const isPopular = popularIndex === index;

						return (
							<PricingCard
								key={`pricing-3-tier-${index}`}
								tier={tier}
								isPopular={isPopular}
								popularLabel={popularLabel}
							/>
						);
					})}
				</div>
			</div>
		</section>
	);
}

interface PricingCardProps {
	tier: NonNullable<Pricing_3_Block["tiers"]>[number];
	isPopular: boolean;
	popularLabel: string;
}

function PricingCard({ tier, isPopular, popularLabel }: PricingCardProps) {
	if (!tier) return null;

	const periodLabel =
		tier.period === "month" ? "/mo" : tier.period === "year" ? "/yr" : "";

	return (
		<Card className="relative flex flex-col">
			{/* Popular Badge */}
			{isPopular && (
				<span className="absolute inset-x-0 -top-3 mx-auto flex h-6 w-fit items-center rounded-full bg-linear-to-br/increasing from-purple-400 to-amber-300 px-3 py-1 text-xs font-medium text-amber-950 ring-1 ring-white/20 ring-offset-1 ring-offset-gray-950/5 ring-inset">
					{popularLabel}
				</span>
			)}

			<CardHeader>
				{/* Plan Name */}
				<CardTitle className="text-lg font-medium">{tier.name}</CardTitle>

				{/* Price */}
				<div className="my-3 flex items-baseline gap-1">
					<span className="text-4xl font-semibold">${tier.price}</span>
					<span className="text-muted-foreground text-sm">{periodLabel}</span>
				</div>

				{/* Per Editor Label */}
				{tier.perEditor && (
					<p className="text-muted-foreground text-xs">Per editor</p>
				)}

				{/* Description */}
				{tier.description && (
					<CardDescription className="mt-2 text-sm">
						{tier.description}
					</CardDescription>
				)}

				{/* CTA Button */}
				<Button
					asChild
					className="mt-4 w-full"
					variant={isPopular ? "default" : "outline"}
				>
					<Link href={tier.ctaHref || "#"}>
						{tier.ctaLabel || "Get Started"}
					</Link>
				</Button>
			</CardHeader>

			<CardContent className="flex-1 space-y-4">
				{/* Divider */}
				<hr className="border-dashed" />

				{/* Features List */}
				<ul className="space-y-3 text-sm">
					{(tier.features ?? []).map((feature, featureIndex) => (
						<li
							key={`pricing-3-tier-${tier.name}-feature-${featureIndex}`}
							className="flex items-start gap-2"
						>
							<Check className="size-4 shrink-0 text-green-600 dark:text-green-400" />
							<span>{feature.text}</span>
						</li>
					))}
				</ul>
			</CardContent>
		</Card>
	);
}

import type { Block } from "payload";

import {
	BLOCK_GROUP_PRICING,
	BLOCK_SLUG_PRICING_3,
} from "@/registry/default/lib/constants/blocks";
import descriptionField from "@/registry/default/lib/fields/description/config";
import headerField from "@/registry/default/lib/fields/header/config";
import subHeaderField from "@/registry/default/lib/fields/subheader/config";

export const Pricing_3_Block: Block = {
	slug: BLOCK_SLUG_PRICING_3,
	admin: {
		group: BLOCK_GROUP_PRICING,
	},
	fields: [
		headerField({
			defaultValue: "Pricing that Scales with You",
			required: false,
		}),
		subHeaderField({
			defaultValue: "Choose the plan that best fits your needs",
			required: false,
		}),
		{
			name: "config",
			type: "group",
			fields: [
				{
					name: "popularIndex",
					type: "number",
					admin: {
						description: "Which tier should show the 'Popular' badge? (0 = first, 1 = second, 2 = third, -1 = none)",
					},
					defaultValue: 1,
					label: "Popular Plan Index (0-based)",
					required: false,
				},
				{
					name: "popularLabel",
					type: "text",
					defaultValue: "Popular",
					label: "Popular Plan Badge Label",
					required: true,
				},
			],
			label: "Config",
		},
		{
			name: "tiers",
			type: "array",
			defaultValue: [
				{
					name: "Starter",
					ctaHref: "/signup",
					ctaLabel: "Get Started",
					description: "Perfect for small teams getting started",
					features: [
						{ text: "Up to 5 editors" },
						{ text: "10GB storage" },
						{ text: "Basic analytics" },
						{ text: "Email support" },
						{ text: "Core features" },
					],
					perEditor: true,
					period: "month",
					price: 29,
				},
				{
					name: "Professional",
					ctaHref: "/signup",
					ctaLabel: "Get Started",
					description: "For growing teams with advanced needs",
					features: [
						{ text: "Up to 20 editors" },
						{ text: "100GB storage" },
						{ text: "Advanced analytics" },
						{ text: "Priority support" },
						{ text: "All features included" },
						{ text: "Custom integrations" },
					],
					perEditor: true,
					period: "month",
					price: 79,
				},
				{
					name: "Enterprise",
					ctaHref: "/contact",
					ctaLabel: "Contact Sales",
					description: "For large organizations with custom requirements",
					features: [
						{ text: "Unlimited editors" },
						{ text: "Unlimited storage" },
						{ text: "Custom analytics" },
						{ text: "24/7 dedicated support" },
						{ text: "All features included" },
						{ text: "Custom integrations" },
						{ text: "SLA guarantee" },
						{ text: "Dedicated account manager" },
					],
					perEditor: false,
					period: "month",
					price: 199,
				},
			],
			fields: [
				{
					name: "name",
					type: "text",
					label: "Plan Name",
					required: true,
				},
				{
					name: "price",
					type: "number",
					label: "Price",
					required: true,
				},
				{
					name: "period",
					type: "select",
					defaultValue: "month",
					label: "Billing Period",
					options: [
						{ label: "Per Month", value: "month" },
						{ label: "Per Year", value: "year" },
						{ label: "One-time", value: "once" },
					],
					required: true,
				},
				{
					name: "perEditor",
					type: "checkbox",
					defaultValue: true,
					label: "Show 'Per Editor' Label",
					required: false,
				},
				descriptionField({
					required: false,
				}),
				{
					name: "ctaLabel",
					type: "text",
					defaultValue: "Get Started",
					label: "Button Label",
					required: true,
				},
				{
					name: "ctaHref",
					type: "text",
					defaultValue: "",
					label: "Button Link",
					required: false,
				},
				{
					name: "features",
					type: "array",
					fields: [
						{
							name: "text",
							type: "text",
							required: true,
						},
					],
					label: "Features List",
					maxRows: 10,
					minRows: 1,
				},
			],
			label: {
				plural: "Pricing Tiers",
				singular: "Pricing Tier",
			},
			maxRows: 4,
			minRows: 0,
		},
	],
	interfaceName: "Pricing_3_Block",
	labels: {
		plural: "Pricing 3's",
		singular: "Pricing 3",
	},
};
